    code_key VARCHAR(80) NOT NULL,
    code_value VARCHAR(120) NOT NULL,
    description VARCHAR(500),
    use_yn CHAR(1) NOT NULL DEFAULT 'Y',
    created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_cpf_code PRIMARY KEY (code_id),
    CONSTRAINT uk_cpf_code_key_value UNIQUE (code_key, code_value),
    CONSTRAINT fk_cpf_code_parent FOREIGN KEY (parent_id) REFERENCES cpf_code (code_id) ON DELETE SET NULL
);
CREATE INDEX ix_cpf_code_parent ON cpf_code (parent_id);
CREATE INDEX ix_cpf_code_use ON cpf_code (use_yn);
COMMENT ON TABLE cpf_code IS 'CPF 시스템 공통 코드';
COMMENT ON COLUMN cpf_code.code_id IS '코드 순번';
COMMENT ON COLUMN cpf_code.parent_id IS '상위 코드 순번';
COMMENT ON COLUMN cpf_code.code_key IS '코드 그룹 키';
COMMENT ON COLUMN cpf_code.code_value IS '코드 값';
COMMENT ON COLUMN cpf_code.description IS '코드 설명';
COMMENT ON COLUMN cpf_code.use_yn IS '사용 여부';
COMMENT ON COLUMN cpf_code.created_by IS '등록자';
COMMENT ON COLUMN cpf_code.created_at IS '등록일시';
COMMENT ON COLUMN cpf_code.updated_by IS '수정자';
COMMENT ON COLUMN cpf_code.updated_at IS '수정일시';
CREATE OR REPLACE FUNCTION cpf_touch_cpf_code() RETURNS trigger AS $$ BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS trg_cpf_touch_cpf_code ON cpf_code;
CREATE TRIGGER trg_cpf_touch_cpf_code BEFORE UPDATE ON cpf_code FOR EACH ROW EXECUTE FUNCTION cpf_touch_cpf_code();

