CREATE TABLE cpf_standard_execution (
    standard_execution_id CHAR(10) NOT NULL,
    execution_name VARCHAR(150) NOT NULL,
    execution_type VARCHAR(20) NOT NULL,
    owner_domain VARCHAR(20) NOT NULL,
    source_module VARCHAR(20) NOT NULL,
    source_class VARCHAR(255) NOT NULL,
    source_method VARCHAR(150) NOT NULL,
    http_method VARCHAR(10),
    endpoint VARCHAR(500),
    operation_id VARCHAR(150),
    description VARCHAR(1000),
    required_permission VARCHAR(150),
    audit_reason_required_yn CHAR(1) NOT NULL DEFAULT 'N',
    visibility VARCHAR(20) NOT NULL DEFAULT 'INTERNAL',
    direct_allowed_yn CHAR(1) NOT NULL DEFAULT 'Y',
    gateway_allowed_yn CHAR(1) NOT NULL DEFAULT 'N',
    source_version VARCHAR(100) NOT NULL,
    registration_status VARCHAR(30) NOT NULL DEFAULT 'REGISTERED',
    first_registered_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_discovered_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_cpf_standard_execution PRIMARY KEY (standard_execution_id),
    CONSTRAINT ck_cpf_standard_execution_id CHECK (standard_execution_id ~ '^[OSB][A-Z]{3}[A-Z0-9]{2}[0-9]{4}$' AND RIGHT(standard_execution_id, 4) <> '0000'),
    CONSTRAINT ck_cpf_standard_execution_type CHECK (execution_type IN ('ONLINE', 'SHARED', 'BATCH'))
);
CREATE INDEX ix_cpf_standard_execution_type ON cpf_standard_execution (execution_type, registration_status);
CREATE INDEX ix_cpf_standard_execution_owner ON cpf_standard_execution (owner_domain, source_module);
CREATE INDEX ix_cpf_standard_execution_source ON cpf_standard_execution (source_class, source_method);
