    transaction_id CHAR(34) NOT NULL,
    parent_segment_id VARCHAR(120),
    transaction_role VARCHAR(40) NOT NULL,
    module_code VARCHAR(20) NOT NULL,
    source_module_code VARCHAR(20),
    target_module_code VARCHAR(20),
    direction VARCHAR(20) NOT NULL,
    call_depth INTEGER NOT NULL DEFAULT 0,
    sequence_no INTEGER NOT NULL DEFAULT 1,
    api_path VARCHAR(500),
    transaction_name VARCHAR(200),
