    downstream_http_status INTEGER,
    result_state VARCHAR(30),
    unknown_result_id VARCHAR(100),
    created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',
    created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_cpf_transaction_segment PRIMARY KEY (segment_id),
    CONSTRAINT uk_cpf_transaction_segment_id UNIQUE (transaction_segment_id)
);
