CREATE TABLE cpf_unknown_result (
    unknown_seq BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    unknown_id VARCHAR(120) NOT NULL,
    unknown_type VARCHAR(40) NOT NULL,
    unknown_status VARCHAR(40) NOT NULL DEFAULT 'CHECK_PENDING',
    transaction_id CHAR(34),
    segment_id VARCHAR(120),
    external_key VARCHAR(200),
    failure_code VARCHAR(100),
    failure_message VARCHAR(1000),
    next_action VARCHAR(100),
    detected_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at TIMESTAMP(3),
    resolved_by VARCHAR(100),
    audit_reason VARCHAR(500),
    created_by VARCHAR(100) NOT NULL DEFAULT 'CPF',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    attempt_count INTEGER NOT NULL DEFAULT 0,
    next_check_at TIMESTAMP(3),
    lease_owner VARCHAR(120),
    lease_until TIMESTAMP(3),
    row_version BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT pk_cpf_unknown_result PRIMARY KEY (unknown_seq),
    CONSTRAINT uk_cpf_unknown_result_id UNIQUE (unknown_id)
);
CREATE INDEX ix_cpf_unknown_result_status ON cpf_unknown_result (unknown_type, unknown_status, detected_at);
