    updated_by VARCHAR(100) NOT NULL DEFAULT 'CPF',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    operation_id VARCHAR(100) NOT NULL,
    request_hash VARCHAR(64) NOT NULL,
